#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <sched.h>

void *thread_func(void *arg)
{
    printf("New thread running with custom parameters.\n");
    // Verify policy and priority if needed, e.g., pthread_getschedparam()
    return NULL;
}

int main()
{
    pthread_attr_t attr;
    struct sched_param param;
    pthread_t thread_id;
    int policy = SCHED_FIFO; // Use a real-time policy to allow high priority setting
    int max_prio;
    int s;

    // 1. Initialize attributes object
    if ((s = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }

    // 2. Determine max priority for the chosen policy (SCHED_FIFO)
    max_prio = sched_get_priority_max(policy);
    if (max_prio == -1) {
        perror("sched_get_priority_max");
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 3. Set the scheduling policy in the attribute object
    if ((s = pthread_attr_setschedpolicy(&attr, policy)) != 0) {
        fprintf(stderr, "Error setting policy: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Set the desired priority parameter
    param.sched_priority = max_prio - 1; // Use a high, valid priority
    if ((s = pthread_attr_setschedparam(&attr, &param)) != 0) {
        fprintf(stderr, "Error setting schedparam: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 5. ESSENTIAL: Set inherit scheduler attribute to EXPLICIT
    // This ensures the custom parameters (policy/priority) take effect
    if ((s = pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED)) != 0) {
        fprintf(stderr, "Error setting inherit sched: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 6. Create the thread with the custom attributes
    if ((s = pthread_create(&thread_id, &attr, thread_func, NULL)) != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    pthread_join(thread_id, NULL);
    pthread_attr_destroy(&attr);

    printf("Thread created and joined successfully.\n");
    return 0;
}
